const b64Apartados = $('Leer CSV de apartados').first().binary.apartados_csv.data;
const b64Ventas = $('Leer CSV de ventas').first().binary.ventas_csv.data;
const txtApartados = Buffer.from(b64Apartados, 'base64').toString('utf8');
const txtVentas = Buffer.from(b64Ventas, 'base64').toString('utf8');

function parsearLineaCSV(linea) {
  const campos = [];
  let actual = '';
  let enComillas = false;
  for (let i = 0; i < linea.length; i++) {
    const ch = linea[i];
    if (ch === '"') {
      enComillas = !enComillas;
    } else if (ch === ',' && !enComillas) {
      campos.push(actual.trim());
      actual = '';
    } else {
      actual += ch;
    }
  }
  campos.push(actual.trim());
  return campos;
}

function parsearCSV(texto) {
  const lineas = texto.split(/\r?\n/).filter(l => l.trim().length > 0);
  const cabeceras = parsearLineaCSV(lineas[0]);
  return lineas.slice(1).map((linea, idx) => {
    const valores = parsearLineaCSV(linea);
    const obj = { _fila: idx + 2 };
    cabeceras.forEach((c, i) => { obj[c] = valores[i] ?? ''; });
    return obj;
  });
}

function limpiarFecha(raw) {
  const texto = String(raw || '').trim();
  const m = texto.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (!m) return null;
  const dia = m[1].padStart(2, '0');
  const mes = m[2].padStart(2, '0');
  const anio = m[3].length === 2 ? '20' + m[3] : m[3];
  return `${anio}-${mes}-${dia}`;
}

function limpiarImporte(raw) {
  const limpio = String(raw ?? '').replace(/€/g, '').replace(/\s+/g, '').replace(',', '.').trim();
  if (!limpio) return null;
  const num = Number(limpio);
  return Number.isFinite(num) ? Math.round(num * 100) / 100 : null;
}

function limpiarNombre(raw) {
  return String(raw || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map(p => p.charAt(0).toLocaleUpperCase('es-ES') + p.slice(1).toLocaleLowerCase('es-ES'))
    .join(' ');
}

const filasApartados = parsearCSV(txtApartados);
const filasVentas = parsearCSV(txtVentas);

const ventas = [];
const descartadosVentas = [];
const formasPagoPorFechaImporte = {};

for (const fv of filasVentas) {
  const fecha = limpiarFecha(fv.fecha);
  const concepto = String(fv.concepto || '').trim();
  const importe = limpiarImporte(fv.importe);
  const forma_pago = String(fv.forma_pago || 'efectivo').trim().toLowerCase() || 'efectivo';

  if (!fecha || !concepto) {
    descartadosVentas.push({
      fila: fv._fila,
      fecha_original: fv.fecha,
      concepto: concepto || fv.fecha,
      importe_original: fv.importe,
      motivo: 'Fila de suma manual o sin fecha válida'
    });
    continue;
  }
  if (/abono|apartado/i.test(concepto)) {
    formasPagoPorFechaImporte[`${fecha}|${importe}`] = forma_pago;
    descartadosVentas.push({
      fila: fv._fila,
      fecha_original: fv.fecha,
      concepto,
      importe_original: String(importe),
      motivo: 'Apunte de abono de apartado en hoja de ventas (se registra en su apartado para no duplicar)'
    });
    continue;
  }
  ventas.push({ fecha, concepto, importe, forma_pago });
}

const grupos = new Map();
for (const fa of filasApartados) {
  const fecha = limpiarFecha(fa.fecha);
  const cliente = limpiarNombre(fa.cliente);
  const telefono = String(fa.telefono || '').trim() || null;
  const producto = String(fa.modelo || '').trim();
  const talla = String(fa.talla || '').trim() || null;
  const precio = limpiarImporte(fa.precio);
  const abono = limpiarImporte(fa.abono);
  const resta = limpiarImporte(fa.resta);
  const notas = String(fa.notas || '').trim();
  const clave = `${cliente.toLowerCase()}|${producto.toLowerCase()}|${talla || ''}`;
  if (!grupos.has(clave)) grupos.set(clave, []);
  grupos.get(clave).push({
    fila: fa._fila,
    clave,
    fecha,
    fecha_original: fa.fecha,
    cliente,
    telefono,
    producto,
    talla,
    precio,
    abono,
    resta,
    notas
  });
}

const apartados = [];
const abonos = [];
const dudosos = [];

for (const [clave, filas] of grupos.entries()) {
  filas.sort((a, b) => (a.fecha || '').localeCompare(b.fecha || '') || (a.fila - b.fila));
  const inicial = filas[0];
  if (!inicial.fecha || inicial.abono === null || inicial.abono < 5) {
    dudosos.push({
      fila: inicial.fila,
      fecha: inicial.fecha_original,
      fecha_iso: inicial.fecha,
      cliente: inicial.cliente,
      producto: inicial.producto,
      talla: inicial.talla,
      precio: inicial.precio,
      importe: inicial.abono,
      notas: inicial.notas,
      motivo: `Abono inicial de ${inicial.abono} € inferior al mínimo permitido de 5 €`
    });
    for (const dep of filas.slice(1)) {
      dudosos.push({
        fila: dep.fila,
        fecha: dep.fecha_original,
        fecha_iso: dep.fecha,
        cliente: dep.cliente,
        producto: dep.producto,
        talla: dep.talla,
        precio: dep.precio,
        importe: dep.abono,
        notas: dep.notas,
        motivo: `Abono posterior (${dep.abono} €) dependiente del apartado dudoso de ${inicial.cliente} (abono inicial < 5 €)`
      });
    }
    continue;
  }

  const fpInicial = formasPagoPorFechaImporte[`${inicial.fecha}|${inicial.abono}`] || 'efectivo';
  apartados.push({
    clave,
    fecha: inicial.fecha,
    cliente: inicial.cliente,
    telefono: inicial.telefono,
    producto: inicial.producto,
    talla: inicial.talla,
    precio: inicial.precio,
    abono_inicial: inicial.abono,
    forma_pago: fpInicial
  });

  for (const sig of filas.slice(1)) {
    const fpAbono = formasPagoPorFechaImporte[`${sig.fecha}|${sig.abono}`] || 'efectivo';
    abonos.push({
      clave_apartado: clave,
      cliente: sig.cliente,
      producto: sig.producto,
      talla: sig.talla,
      fecha: sig.fecha,
      importe: sig.abono,
      forma_pago: fpAbono,
      notas: sig.notas
    });
  }
}

return [{ json: { apartados, abonos, ventas, dudosos, descartadosVentas } }];

const limpio = $('Limpiar y agrupar').first().json;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';

const apartadosExistentes = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/apartados`,
  headers: { 'X-API-Key': apiKey },
  json: true
});
const abonosExistentes = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/abonos`,
  headers: { 'X-API-Key': apiKey },
  json: true
});
const ventasExistentes = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/ventas`,
  headers: { 'X-API-Key': apiKey },
  json: true
});

const mapaApartados = {};
for (const ap of (apartadosExistentes || [])) {
  const clave = `${String(ap.cliente).toLowerCase()}|${String(ap.producto).toLowerCase()}|${ap.talla || ''}`;
  if (ap.fecha) {
    mapaApartados[`${clave}|${ap.fecha}`] = ap.id;
  }
  mapaApartados[clave] = ap.id;
}

const apartadosNuevos = [];
const apartadosOmitidos = [];
for (const ap of limpio.apartados) {
  const idExistente = mapaApartados[`${ap.clave}|${ap.fecha}`];
  if (idExistente) {
    apartadosOmitidos.push({ ...ap, id: idExistente });
  } else {
    apartadosNuevos.push(ap);
  }
}

const ventasNuevas = [];
const ventasOmitidas = [];
for (const v of limpio.ventas) {
  const yaExiste = (ventasExistentes || []).some(ve =>
    ve.fecha === v.fecha &&
    String(ve.concepto).trim().toLowerCase() === v.concepto.toLowerCase() &&
    Math.abs(Number(ve.importe) - Number(v.importe)) < 0.01
  );
  if (yaExiste) {
    ventasOmitidas.push(v);
  } else {
    ventasNuevas.push(v);
  }
}

return [{
  json: {
    ...limpio,
    mapaApartados,
    abonosExistentes: abonosExistentes || [],
    apartadosNuevos,
    apartadosOmitidos,
    ventasNuevas,
    ventasOmitidas
  }
}];

const estado = $input.first().json;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';
const mapaApartados = { ...(estado.mapaApartados || {}) };
const apartadosCreados = [];

for (const ap of estado.apartadosNuevos) {
  const creado = await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/api/apartados`,
    headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
    body: {
      cliente: ap.cliente,
      telefono: ap.telefono,
      producto: ap.producto,
      talla: ap.talla,
      precio: ap.precio,
      abono_inicial: ap.abono_inicial,
      forma_pago: ap.forma_pago,
      fecha: ap.fecha
    },
    json: true
  });
  mapaApartados[ap.clave] = creado.id;
  mapaApartados[`${ap.clave}|${ap.fecha}`] = creado.id;
  apartadosCreados.push(creado);
}

return [{
  json: {
    ...estado,
    mapaApartados,
    apartadosCreados
  }
}];

const estado = $input.first().json;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';
const abonosCreados = [];
const abonosOmitidos = [];

for (const ab of estado.abonos) {
  const apartadoId = estado.mapaApartados[ab.clave_apartado];
  if (!apartadoId) continue;
  const yaExiste = (estado.abonosExistentes || []).some(ex =>
    Number(ex.apartado_id) === Number(apartadoId) &&
    ex.fecha === ab.fecha &&
    Math.abs(Number(ex.importe) - Number(ab.importe)) < 0.01
  );
  if (yaExiste) {
    abonosOmitidos.push({ ...ab, apartado_id: apartadoId });
    continue;
  }
  const creado = await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/api/apartados/${apartadoId}/abonos`,
    headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
    body: {
      importe: ab.importe,
      forma_pago: ab.forma_pago,
      fecha: ab.fecha
    },
    json: true
  });
  abonosCreados.push({ ...ab, apartado_id: apartadoId, estado_apartado: creado.estado });
}

return [{
  json: {
    ...estado,
    abonosCreados,
    abonosOmitidos
  }
}];

const estado = $input.first().json;
const apiKey = $env.API_KEY;
const baseUrl = 'http://tienda:8000';
const ventasCreadas = [];

for (const v of estado.ventasNuevas) {
  const creada = await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/api/ventas`,
    headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
    body: {
      concepto: v.concepto,
      importe: v.importe,
      forma_pago: v.forma_pago,
      fecha: v.fecha
    },
    json: true
  });
  ventasCreadas.push(creada);
}

const filasDudososHtml = estado.dudosos.map(d =>
  `<tr>` +
  `<td>${d.fecha} (${d.fecha_iso || ''})</td>` +
  `<td><b>${d.cliente}</b></td>` +
  `<td>${d.producto} (T${d.talla || '-'})</td>` +
  `<td>${d.precio} €</td>` +
  `<td>${d.importe} €</td>` +
  `<td>${d.motivo}${d.notas ? ' · Nota: ' + d.notas : ''}</td>` +
  `</tr>`
).join('');

const filasVentasDescartadasHtml = (estado.descartadosVentas || []).map(dv =>
  `<tr>` +
  `<td>${dv.fecha_original || '-'}</td>` +
  `<td>${dv.concepto}</td>` +
  `<td>${dv.importe_original}</td>` +
  `<td>${dv.motivo}</td>` +
  `</tr>`
).join('');

const htmlInforme =
  `<h2>📋 Informe de migración del Excel · Zapatería Paso Firme</h2>` +
  `<p>Hola Marisa, se ha ejecutado la migración de los ficheros CSV de la tienda.</p>` +
  `<h3>Resumen de la ejecución</h3>` +
  `<ul>` +
  `<li><b>Apartados creados ahora:</b> ${estado.apartadosCreados.length} (omitidos por existir ya: ${estado.apartadosOmitidos.length})</li>` +
  `<li><b>Abonos posteriores registrados ahora:</b> ${estado.abonosCreados.length} (omitidos por existir ya: ${estado.abonosOmitidos.length})</li>` +
  `<li><b>Ventas registradas ahora:</b> ${ventasCreadas.length} (omitidas por existir ya: ${estado.ventasOmitidas.length})</li>` +
  `<li><b>Casos dudosos NO cargados:</b> ${estado.dudosos.length} fila(s)</li>` +
  `</ul>` +
  `<h3>⚠️ Casos dudosos de apartados/abonos (no cargados — pendientes de tu decisión)</h3>` +
  `<table border="1" cellpadding="6" style="border-collapse:collapse">` +
  `<tr><th>Fecha</th><th>Cliente</th><th>Producto</th><th>Precio</th><th>Abono</th><th>Motivo</th></tr>` +
  `${filasDudososHtml}` +
  `</table>` +
  `<h3>ℹ️ Filas excluidas de la hoja de ventas (totales a mano y abonos ya incluidos en apartados)</h3>` +
  `<table border="1" cellpadding="6" style="border-collapse:collapse">` +
  `<tr><th>Fecha</th><th>Concepto</th><th>Importe</th><th>Motivo</th></tr>` +
  `${filasVentasDescartadasHtml}` +
  `</table>` +
  `<p>Revisa los casos dudosos y regístralos manualmente en la app si procede. — Flujo 09</p>`;

return [{
  json: {
    resumen: {
      apartados_creados: estado.apartadosCreados.length,
      apartados_omitidos: estado.apartadosOmitidos.length,
      abonos_creados: estado.abonosCreados.length,
      abonos_omitidos: estado.abonosOmitidos.length,
      ventas_creadas: ventasCreadas.length,
      ventas_omitidas: estado.ventasOmitidas.length,
      casos_dudosos: estado.dudosos.length
    },
    dudosos: estado.dudosos,
    htmlInforme
  }
}];
